// v23.xx (gfx36), HIS ORDER 2026-10-12 (the graphics program, item 9, atmosphere; his answer 20, gritty and grounded): STEAM AND
// EMBERS. COLD STORAGE is a cold store whose machines still run, and nothing on it breathed. Two things now, in the air pass (gfxAir,
// in the world transform, before the light and the fog of war sheet, so the dark and the fog fall on them like on everything else):
// - steam vents: refrigeration exhausts on the ground outside the south face of about half the COLD STORAGE buildings (two on a big
//   one), each puffing a slow column of steam that rises, spreads, leans with its own draught and thins out. Where the vents are is a
//   pure function of the building rectangles (grit), worked out once a map (GFXVENTS) and skipped where a wall, a roof or water sits;
//   every other map has none. Each puff is a function of the raid clock: no random draw, nothing stored per frame.
// - embers: a machine you have vented with a shot to its weak spot (overheat) throws a few sparks up off its back while it cools,
//   only while you can see it (VIS), so they never mark a machine through a wall.
// Effects LOW draws half as many puffs and sparks. GFX.bypass and a bot raid draw none.
var GFXVENTS=[];
function gfxVents(){
  var mp=(typeof G!=='undefined'&&G)?G.map:null, B, i, b, k, x, y, j, w, ok, ww, wq;
  if(GFXE.vm===mp) return GFXVENTS;
  GFXE.vm=mp; GFXVENTS=[];
  if(!mp||mp.fixed!=='cold') return GFXVENTS;
  B=mp.buildings||[]; ww=mp.walls||[]; wq=mp.water||[];
  for(i=0;i<B.length;i++){
    b=B[i];
    for(k=0;k<(b.big?2:1);k++){
      if(grit(b.x+k*131,b.y+k*71)>0.62) continue;
      x=Math.round(b.x+30+grit(b.y+k*17,b.x+k*29)*Math.max(0,b.w-60)); y=b.y+b.h+20;
      ok=!roofAt(x,y);
      for(j=0;ok&&j<ww.length;j++){ w=ww[j]; if(x>w.x-14&&x<w.x+w.w+14&&y>w.y-14&&y<w.y+w.h+14) ok=false; }
      for(j=0;ok&&j<wq.length;j++){ w=wq[j]; if(x>w.x-10&&x<w.x+w.w+10&&y>w.y-10&&y<w.y+w.h+10) ok=false; }
      if(ok) GFXVENTS.push({x:x,y:y,ph:grit(x,y),wd:(grit(y,x)<0.5?-1:1)});
    }
  }
  return GFXVENTS;
}
function gfxSteamSpr(){
  var st=gfxStore('gfxE'), m=st.m, c, x, gr;
  if(m.steam) return m.steam;
  c=document.createElement('canvas'); c.width=c.height=64; x=c.getContext('2d');
  gr=x.createRadialGradient(32,32,0,32,32,32);
  gr.addColorStop(0,'rgba(236,240,246,.9)'); gr.addColorStop(0.5,'rgba(220,228,236,.5)'); gr.addColorStop(1,'rgba(210,218,228,0)');
  x.fillStyle=gr; x.fillRect(0,0,64,64); m.steam=c; st.n++;
  return c;
}
function gfxEmberSpr(){
  var st=gfxStore('gfxE'), m=st.m, c, x, gr;
  if(m.ember) return m.ember;
  c=document.createElement('canvas'); c.width=c.height=16; x=c.getContext('2d');
  gr=x.createRadialGradient(8,8,0,8,8,8);
  gr.addColorStop(0,'rgba(255,236,180,1)'); gr.addColorStop(0.35,'rgba(255,150,60,.85)'); gr.addColorStop(1,'rgba(220,70,20,0)');
  x.fillStyle=gr; x.fillRect(0,0,16,16); m.ember=c; st.n++;
  return c;
}
function gfxSteamDraw(){
  var V=gfxVents(), i, v, k, N, q, P=3.4, t=G.t||0, Z=ZOOM(), n=0, R, z, x, spr;
  if(!V.length) return 0;
  var vx0=VX-80, vy0=VY-40, vx1=VX+W/Z+80, vy1=VY+H/Z+160;
  N=(CFG.fxLevel===0)?3:6;
  for(i=0;i<V.length;i++){
    v=V[i];
    if(v.x<vx0||v.x>vx1||v.y<vy0||v.y>vy1) continue;
    if(!n){ spr=gfxSteamSpr(); wc.save(); wc.globalCompositeOperation='source-over'; }
    for(k=0;k<N;k++){
      q=t/P+k/N+v.ph; q=q-Math.floor(q);
      z=4+104*q; R=8+30*q;
      x=v.x+Math.sin(t*0.5+v.ph*6.2832+k)*4*q+v.wd*30*q*q;
      wc.globalAlpha=Math.max(0,Math.min(1,0.5*(q<0.12?q/0.12:Math.pow((1-q)/0.88,1.4))));
      wc.drawImage(spr,x-R,v.y-z-R,R*2,R*2);
      n++;
    }
  }
  if(n) wc.restore();
  return n;
}
function gfxEmberDraw(){
  var i, e, k, q, t=G.t||0, n=0, spr, x, z, N=(CFG.fxLevel===0)?3:6;
  for(i=0;i<VIS.length;i++){
    e=VIS[i];
    if(!e||!(e.overheat>0)||!(e.hp>0)) continue;
    if(!n){ spr=gfxEmberSpr(); wc.save(); wc.globalCompositeOperation='lighter'; }
    for(k=0;k<N;k++){
      q=t/0.9+k/N+e.x*0.013; q=q-Math.floor(q);
      x=e.x+Math.sin(k*2.39+e.y*0.01)*10+Math.sin(t*3+k)*4*q;
      z=18+46*q;
      wc.globalAlpha=Math.max(0,Math.min(1,(1-q)*Math.min(1,e.overheat/0.6)));
      wc.drawImage(spr,x-2.5,e.y-z-2.5,5,5);
      n++;
    }
  }
  if(n) wc.restore();
  return n;
}
// ===== GFX-E end =====

