{v:'VER',what:'gfx36, his order 2026-10-12 (the graphics program, item 9): COLD STORAGE has steam vents and one in view draws steam; a vented machine in sight throws embers and a cool one none; THE COLD MILE has no vents',
 run:function(){
   var bad=[], g=null, p, v, n, spr, e=null, i, ex, ey, eo, fc;
   var cnt=function(img){ var q=0, orig=wc.drawImage; wc.drawImage=function(im){ if(im===img) q++; return orig.apply(wc,arguments); }; try{ __frame(0.016); } finally { delete wc.drawImage; } return q; };
   try{
     if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)) return 'SKIP: this fixture has no gfx stage';
     g=__gfxStage({frames:2,cond:'day',wx:'clear'});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(g.sim) return 'SKIP: the staged raid is a sim raid';
     if(typeof gfxVents!=='function') return 'no steam vents: no gfxVents';
     GFX.bypass=0; G.shake=0; p=g.player;
     if(!(gfxVents().length>0)) bad.push('COLD STORAGE has '+GFXVENTS.length+' steam vents');
     else {
       v=GFXVENTS[0]; p.x=v.x; p.y=v.y+140; p.vx=0; p.vy=0; G.anchX=undefined;
       __frame(0.016); spr=gfxSteamSpr();
       n=cnt(spr); if(!(n>0)) bad.push('a steam vent in view drew '+n+' puffs');
     }
     for(i=0;i<G.ents.length;i++){ if(G.ents[i].hp>0&&(G.ents[i].kind==='sentry'||G.ents[i].kind==='crawler')){ e=G.ents[i]; break; } }
     if(e){
       ex=e.x; ey=e.y; eo=e.overheat; fc=p.face;
       e.x=p.x+70; e.y=p.y; p.face=0; e.overheat=3;
       __frame(0.016);
       if(VIS.indexOf(e)<0) bad.push('SKIP: staging: the machine beside him is not in sight');
       else {
         spr=gfxEmberSpr();
         n=cnt(spr); if(!(n>0)) bad.push('a vented machine in sight threw '+n+' embers');
         e.overheat=0;
         n=cnt(spr); if(n!==0) bad.push('a cool machine threw '+n+' embers');
       }
       e.x=ex; e.y=ey; e.overheat=eo; p.face=fc;
     }
     try{ __endRaid('abandon'); }catch(_e1){}
     g=__gfxStage({frames:1,cond:'day',wx:'clear',mapIx:1});
     if(g&&!g.sim&&G.map&&G.map.fixed==='mile'){ n=gfxVents().length; if(n!==0) bad.push('THE COLD MILE has '+n+' steam vents'); }
   }catch(e2){ bad.push('threw: '+(e2&&e2.message||e2)); }
   finally{
     keys={};
     try{ var g2=__state(); if(g2&&!g2.over&&!g2.sim) __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
